def score_idea(name, pain, feasible, distinct, weights=(0.4, 0.35, 0.25), floor=3.5):
    scores = {"痛感": pain, "可行": feasible, "差异": distinct}
    veto = [k for k, v in scores.items() if v <= 2]          # 致命短板
    total = sum(s * w for s, w in zip(scores.values(), weights))
    if veto:
        return total, "否决(" + ",".join(veto) + ")"
    return total, "通过" if total >= floor else "低于阈值,建议换题"

ideas = [("周报助手", 4, 5, 4), ("文档问答", 5, 4, 2), ("通用聊天框", 2, 5, 1)]
for name, *s in sorted(ideas, key=lambda x: -score_idea(x[0], *x[1:])[0]):
    total, verdict = score_idea(name, *s)
    print(f"{name}: {total:.2f} -> {verdict}")

from collections import deque

def topo_order(tasks):
    dur = {n: d for n, d, _ in tasks}
    pre = {n: p for n, _, p in tasks}
    suc = {n: [] for n in dur}
    indeg = {n: len(p) for n, p in pre.items()}
    for n, ps in pre.items():
        for p in ps:
            suc[p].append(n)
    q = deque(sorted(n for n, d in indeg.items() if d == 0))
    order = []
    while q:
        n = q.popleft(); order.append(n)
        for m in suc[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                q.append(m)
    assert len(order) == len(dur), "依赖有环"
    return order

def critical_path(tasks):
    order = topo_order(tasks)
    dur = {n: d for n, d, _ in tasks}; pre = {n: p for n, _, p in tasks}
    ef = {}
    for n in order:
        ef[n] = max([ef[p] for p in pre[n]], default=0) + dur[n]
    return max(ef.values()), ef
